export function storedLanguage(): LanguageCode {
  const saved = localStorage.getItem('clary.language')
  return languages.some((language) => language.code === saved) ? saved as LanguageCode : 'es'
}

export function translate(language: LanguageCode, key: TranslationKey) {
  return dictionaries[language][key] ?? dictionaries.es[key]
}

export function localeForLanguage(language: LanguageCode) {
  return languageLocales[language]
}
